    fn what_the_user_changes_is_never_put_back() {
        let dir = project("user");
        let guard = Guard::start(SendMode::Code, &dir).unwrap();
        std::fs::create_dir_all(dir.join("spec/copied")).unwrap();
        std::fs::write(dir.join("spec/copied/c.pi"), "copied\\n").unwrap();
        std::fs::write(dir.join("spec/ui/a.pi"), "by the user\\n").unwrap();
        // The task changes index.pi, then the user changes it again.
        std::fs::write(dir.join("spec/index.pi"), "by the task\\n").unwrap();
        guard.touched_if_new(&[dir.join("spec/index.pi")]);
        std::thread::sleep(std::time::Duration::from_millis(20));
        std::fs::write(dir.join("spec/index.pi"), "by the user, after\\n").unwrap();
        let done = guard.finish();
        assert_eq!(std::fs::read_to_string(dir.join("spec/copied/c.pi")).unwrap(), "copied\\n");
        assert_eq!(std::fs::read_to_string(dir.join("spec/ui/a.pi")).unwrap(), "by the user\\n");
        assert_eq!(
            std::fs::read_to_string(dir.join("spec/index.pi")).unwrap(),
            "by the user, after\\n"
        );
        assert!(done.put_back.is_empty());
        assert_eq!(done.left, [PathBuf::from("index.pi")]);
        std::fs::remove_dir_all(&dir).ok();
    }

    /// What a run beside it may change, as a Spec task beside a Code task,
    /// is never put back.
    #[test]
    fn a_code_run_keeps_what_a_spec_run_beside_it_changes() {
        let dir = project("beside");
        let guard = Guard::start(SendMode::Code, &dir).unwrap();
        let spec_run = Writing::start(Some(SendMode::Spec), &dir);
        std::fs::write(dir.join("spec/index.pi"), "by the spec task\\n").unwrap();
        guard.touched_if_new(&[dir.join("spec/index.pi")]);
        let done = guard.finish();
        drop(spec_run);
        assert_eq!(
            std::fs::read_to_string(dir.join("spec/index.pi")).unwrap(),
            "by the spec task\\n"
        );
        assert!(done.put_back.is_empty());
        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn the_applications_own_saves_are_kept() {
        let dir = project("saved");
        let guard = Guard::start(SendMode::Code, &dir).unwrap();
        let file = dir.join("spec/index.pi");
        saving(&file, b"saved\\n");
        std::fs::write(&file, "saved\\n").unwrap();
        guard.touched_if_new(&[file.clone()]);
        assert!(guard.finish().put_back.is_empty());
        assert_eq!(std::fs::read_to_string(&file).unwrap(), "saved\\n");
        std::fs::remove_dir_all(&dir).ok();
    }

